int donotq_apply_cfg ( struct iter_donotq * dq , struct config_file * cfg ) { regional_free_all ( dq -> region ) ; addr_tree_init ( & dq -> tree ) ; if ( cfg -> donotquery_localhost ) { if ( ! donotq_str_cfg ( dq , "127.0.0.0/8" ) ) { return 0 ; } if ( cfg -> do_ip6 ) { if ( ! donotq_str_cfg ( dq , "::1" ) ) { return 0 ; } } } addr_tree_init_parents ( & dq -> tree ) ; return 1 ; } 